  "apiRequestsPerHour",
  "webhooks",
];

describe("config/plan-limits", () => {
  it("declares limits for every plan id", () => {
    for (const plan of PLAN_IDS) {
      expect(getPlanLimits(plan).plan).toBe(plan);
    }
    expect([...PLAN_ORDER].sort()).toEqual([...PLAN_IDS].sort());
  });

